class Solution:
    def reorderedPowerOf2(self, n: int) -> bool:
        target = sorted(str(n))
        return any(sorted(str(1 << i)) == target for i in range(30))

class Solution {
public:
    bool reorderedPowerOf2(int n) {
        string target = to_string(n);
        sort(target.begin(), target.end());
        for (int i = 0; i < 30; i++) {
            string s = to_string(1 << i);
            sort(s.begin(), s.end());
            if (s == target) return true;
        }
        return false;
    }
};

class Solution {
    public boolean reorderedPowerOf2(int n) {
        char[] target = Integer.toString(n).toCharArray();
        Arrays.sort(target);
        String targetStr = new String(target);
        for (int i = 0; i < 30; i++) {
            char[] s = Integer.toString(1 << i).toCharArray();
            Arrays.sort(s);
            if (new String(s).equals(targetStr)) return true;
        }
        return false;
    }
}

var reorderedPowerOf2 = function(n) {
    const target = String(n).split('').sort().join('');
    for (let i = 0; i < 30; i++) {
        const s = String(1 << i).split('').sort().join('');
        if (s === target) return true;
    }
    return false;
};
